    std::unique_ptr<n::NativeNotesImageDecoder>decoder;std::unique_ptr<n::NativeNotesImagePlayback>images;std::unique_ptr<n::NativeMediaRequestBroker>broker;n::NativeMediaRequestBroker::Client client{};
