    d::Note note{.id=noteID,.kind=d::NoteKind::image,.x=20,.y=20,.width=200,.height=150,.createdAt=0};note.media=d::makeWindowsMediaReference("C:\\owned-synthetic\\video.mp4","video.mp4",2,2,"video",10,1);unsigned saves{};
    m::NotesState state({note},{[&](const auto&){++saves;},[&](auto){++saves;}});state.setWorkspaceBounds({0,0,640,360});n::LayerRasterizer raster;n::NativeNotesWorkspaceStyle style;style.palette=m::NotesPalette::source(true,{.98,.83,.12,1});style.editor={{.12,.12,.12,1},style.palette.accent};n::NativeNotesWorkspaceOptions options;options.raster.pixelsPerPoint=1;if(shared){options.mediaBroker=broker.get();options.mediaClient=client;}else options.videoPlayback=&video;
    auto workspaceOwner=std::make_unique<n::NativeNotesWorkspace>(window.hwnd,state,raster,style,options);auto&workspace=*workspaceOwner;n::LayerComposition composition;
    auto accept=[&](double time){if(broker)broker->accept(17,time);return workspace.acceptMedia(17,time);};auto sample=[&](double time){if(broker)broker->sample(time);return workspace.sampleMedia(time);};auto requiresFrames=[&](double time){return workspace.requiresFrames(time)||(broker&&broker->requiresFrames());};
