    workspace.updatePose(pose(0));accept(0);publish();if(broker){const auto deadline=GetTickCount64()+10000;while(workspace.entries()[0].after[0].textureID.empty()){const auto now=GetTickCount64();check(now<deadline,"One shared worker supplies the injected movie poster");MsgWaitForMultipleObjectsEx(0,nullptr,static_cast<DWORD>(deadline-now),QS_POSTMESSAGE,MWMO_INPUTAVAILABLE);MSG message{};while(PeekMessageW(&message,window.hwnd,Window::message,Window::message,PM_REMOVE)){}accept(0);publish();}}
    check(workspace.entries().size()==1&&workspace.entries()[0].after.size()==4&&!workspace.entries()[0].after[0].textureID.empty(),"Source movie card borrows actual retained poster in shared composition");
    renderer.draw(false);const auto pixels=renderer.readback();const auto offset=(std::size_t(90)*pixels.width+100)*4;check(pixels.pixels[offset+2]>250&&pixels.pixels[offset]<3,"Injected movie paints owned red pixels through original card geometry");check(!requiresFrames(0)&&!workspace.mediaNextWakeTime(),"Initially paused video card needs no permanent frame or deadline");
    probe->fresh=false;check(workspace.toggleMedia(noteID,1)&&requiresFrames(1),"Source footer starts same-device playback");sample(1);publish();
    const auto posterBinding=workspace.entries()[0].after[0].textureID;const auto priorPublication=workspace.compositionRevision();const auto priorPublicationCount=publications;
    check(posterBinding.ends_with(".poster"),"Play without a decoded tick keeps the already published poster");
    probe->fresh=true;sample(1.001);workspace.uploadMedia(renderer);
    check(workspace.entries()[0].after[0].textureID!=posterBinding&&workspace.compositionRevision()>priorPublication,"Delayed first live frame signals structural texture rebinding to the owner");
    publish();check(publications==priorPublicationCount+1&&publishedRevision==workspace.compositionRevision(),"Production owner revision comparison republishes the delayed texture binding");const auto resources=renderer.stats();const auto rasters=raster.stats().rasterizations;
    allocations=0;counting=true;try{for(unsigned f=0;f<120;++f){const auto time=1.01+double(f)/60;probe->position=double(f)/60;probe->fresh=true;sample(time);auto p=pose(time);p.workspaceToScreen.values[12]=double(f)*.01;workspace.updatePose(p);publish();}}catch(...){counting=false;throw;}counting=false;
    check(allocations==0&&renderer.stats().mediaTargetAllocations==resources.mediaTargetAllocations&&renderer.stats().textureUploads==resources.textureUploads&&raster.stats().rasterizations==rasters,"120 live-video/tilt frames retain layouts, texture bindings, resources and CPU storage");
    workspace.toggleMedia(noteID,3.1);publish();auto tilted=pose(3.2);tilted.workspaceToScreen=c::Matrix4::translation(3,4)*c::Matrix4::scale(.93,.9);tilted.workspaceToScreen.values[3]=.00005;workspace.updatePose(tilted);
