    check(workspace.beginMediaSeek(noteID,rail(.25),3.2)&&workspace.mediaSeeking(),"Projected source rail starts owner gesture");check(workspace.updateMediaSeek(rail(.75),3.3)&&probe->seeks==seeks&&saves==0,"Pointer drag changes only preview; no repeated native seek or persistence");
    check(workspace.endMediaSeek(3.4)&&!workspace.mediaSeeking()&&probe->seeks==seeks+1&&std::abs(probe->position-7.5)<1e-8,"Pointer-up submits exactly one perspective-correct source seek");accept(3.4);publish();check(!requiresFrames(3.4),"Paused seek settles without a continuing rendering clock");
    workspace.setPresentation(false,true);publish();check(workspace.entries().size()==1&&!workspace.hitTest(rail(.5))&&!workspace.toggleMedia(noteID,3.5),"Outgoing movie preserves poster but rejects input");sample(4.1);workspace.settleOutgoing();publish();check(workspace.entries().empty()&&!workspace.mediaNextWakeTime()&&saves==0,"Section close clears movie demand without modifying its reference");
